25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * PTP clock module
33	 */
34	module ptp_clock #
35	(
36	    parameter PERIOD_NS_WIDTH = 4,
37	    parameter OFFSET_NS_WIDTH = 4,
38	    parameter DRIFT_NS_WIDTH = 4,
39	    parameter FNS_WIDTH = 16,
40	    parameter PERIOD_NS = 4'h6,
41	    parameter PERIOD_FNS = 16'h6666,
42	    parameter DRIFT_ENABLE = 1,
43	    parameter DRIFT_NS = 4'h0,
44	    parameter DRIFT_FNS = 16'h0002,
45	    parameter DRIFT_RATE = 16'h0005,
46	    parameter PIPELINE_OUTPUT = 0
47	)
48	(
49	    input  wire                       clk,
50	    input  wire                       rst,
51	
52	    /*
53	     * Timestamp inputs for synchronization
54	     */
55	    input  wire [95:0]                input_ts_96,
56	    input  wire                       input_ts_96_valid,
57	    input  wire [63:0]                input_ts_64,
58	    input  wire                       input_ts_64_valid,
59	
60	    /*
61	     * Period adjustment
62	     */
63	    input  wire [PERIOD_NS_WIDTH-1:0] input_period_ns,
64	    input  wire [FNS_WIDTH-1:0]       input_period_fns,
65	    input  wire                       input_period_valid,
66	
67	    /*
68	     * Offset adjustment
69	     */
70	    input  wire [OFFSET_NS_WIDTH-1:0] input_adj_ns,
71	    input  wire [FNS_WIDTH-1:0]       input_adj_fns,
72	    input  wire [15:0]                input_adj_count,
73	    input  wire                       input_adj_valid,
74	    output wire                       input_adj_active,
75	
76	    /*
77	     * Drift adjustment
78	     */
79	    input  wire [DRIFT_NS_WIDTH-1:0]  input_drift_ns,
80	    input  wire [FNS_WIDTH-1:0]       input_drift_fns,
81	    input  wire [15:0]                input_drift_rate,
82	    input  wire                       input_drift_valid,
83	
84	    /*
85	     * Timestamp outputs
86	     */
87	    output wire [95:0]                output_ts_96,
88	    output wire [63:0]                output_ts_64,
89	    output wire                       output_ts_step,
90	
91	    /*
92	     * PPS output
93	     */
94	    output wire                       output_pps
95	);
96	
97	parameter INC_NS_WIDTH = $clog2(2**PERIOD_NS_WIDTH + 2**OFFSET_NS_WIDTH + 2**DRIFT_NS_WIDTH);
98	
99	localparam [30:0] NS_PER_S = 31'd1_000_000_000;
100	
101	reg [PERIOD_NS_WIDTH-1:0] period_ns_reg = PERIOD_NS;
102	reg [FNS_WIDTH-1:0] period_fns_reg = PERIOD_FNS;
103	
104	reg [OFFSET_NS_WIDTH-1:0] adj_ns_reg = 0;
105	reg [FNS_WIDTH-1:0] adj_fns_reg = 0;
106	reg [15:0] adj_count_reg = 0;
107	reg adj_active_reg = 0;
108	
109	reg [DRIFT_NS_WIDTH-1:0] drift_ns_reg = DRIFT_NS;
110	reg [FNS_WIDTH-1:0] drift_fns_reg = DRIFT_FNS;
111	reg [15:0] drift_rate_reg = DRIFT_RATE;
112	
113	reg [INC_NS_WIDTH-1:0] ts_inc_ns_reg = 0;
114	reg [FNS_WIDTH-1:0] ts_inc_fns_reg = 0;
115	reg [INC_NS_WIDTH-1:0] ts_inc_ns_delay_reg = 0;
116	reg [FNS_WIDTH-1:0] ts_inc_fns_delay_reg = 0;
117	reg [30:0] ts_inc_ns_ovf_reg = 0;
118	reg [FNS_WIDTH-1:0] ts_inc_fns_ovf_reg = 0;
119	
120	reg [47:0] ts_96_s_reg = 0;
121	reg [29:0] ts_96_ns_reg = 0;
122	reg [FNS_WIDTH-1:0] ts_96_fns_reg = 0;
123	reg [29:0] ts_96_ns_inc_reg = 0;
124	reg [FNS_WIDTH-1:0] ts_96_fns_inc_reg = 0;
125	reg [30:0] ts_96_ns_ovf_reg = 31'h7fffffff;
126	reg [FNS_WIDTH-1:0] ts_96_fns_ovf_reg = 16'hffff;
127	
128	reg [47:0] ts_64_ns_reg = 0;
129	reg [FNS_WIDTH-1:0] ts_64_fns_reg = 0;
130	
131	reg ts_step_reg = 1'b0;
132	
133	reg [15:0] drift_cnt = 0;
134	
135	reg [47:0] temp;
136	
137	reg pps_reg = 0;
138	
139	assign input_adj_active = adj_active_reg;
140	
141	generate
142	
143	if (PIPELINE_OUTPUT > 0) begin
144	
145	    // pipeline
146	    (* shreg_extract = "no" *)
147	    reg [95:0]  output_ts_96_reg[0:PIPELINE_OUTPUT-1];
148	    (* shreg_extract = "no" *)
149	    reg [63:0]  output_ts_64_reg[0:PIPELINE_OUTPUT-1];
150	    (* shreg_extract = "no" *)
151	    reg         output_ts_step_reg[0:PIPELINE_OUTPUT-1];
152	    (* shreg_extract = "no" *)
153	    reg         output_pps_reg[0:PIPELINE_OUTPUT-1];
154	
155	    assign output_ts_96 = output_ts_96_reg[PIPELINE_OUTPUT-1];
156	    assign output_ts_64 = output_ts_64_reg[PIPELINE_OUTPUT-1];
157	    assign output_ts_step = output_ts_step_reg[PIPELINE_OUTPUT-1];
158	    assign output_pps = output_pps_reg[PIPELINE_OUTPUT-1];
159	
160	    integer i;
161	
162	    initial begin
163	        for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
164	            output_ts_96_reg[i] = 96'd0;
165	            output_ts_64_reg[i] = 64'd0;
166	            output_ts_step_reg[i] = 1'b0;
167	            output_pps_reg[i] = 1'b0;
168	        end
169	    end
170	
171	    always @(posedge clk) begin
172	        output_ts_96_reg[0][95:48] <= ts_96_s_reg;
173	        output_ts_96_reg[0][47:46] <= 2'b00;
174	        output_ts_96_reg[0][45:16] <= ts_96_ns_reg;
175	        output_ts_96_reg[0][15:0]  <= {ts_96_fns_reg, 16'd0} >> FNS_WIDTH;
176	        output_ts_64_reg[0][63:16] <= ts_64_ns_reg;
177	        output_ts_64_reg[0][15:0]  <= {ts_64_fns_reg, 16'd0} >> FNS_WIDTH;
178	        output_ts_step_reg[0] <= ts_step_reg;
179	        output_pps_reg[0] <= pps_reg;
180	
181	        for (i = 0; i < PIPELINE_OUTPUT-1; i = i + 1) begin
182	            output_ts_96_reg[i+1] <= output_ts_96_reg[i];
183	            output_ts_64_reg[i+1] <= output_ts_64_reg[i];
184	            output_ts_step_reg[i+1] <= output_ts_step_reg[i];
185	            output_pps_reg[i+1] <= output_pps_reg[i];
186	        end
187	
188	        if (rst) begin
189	            for (i = 0; i < PIPELINE_OUTPUT; i = i + 1) begin
190	                output_ts_96_reg[i] <= 96'd0;
191	                output_ts_64_reg[i] <= 64'd0;
192	                output_ts_step_reg[i] <= 1'b0;
193	                output_pps_reg[i] <= 1'b0;
194	            end
195	        end
196	    end
197	
198	end else begin
199	
200	    assign output_ts_96[95:48] = ts_96_s_reg;
201	    assign output_ts_96[47:46] = 2'b00;
202	    assign output_ts_96[45:16] = ts_96_ns_reg;
203	    assign output_ts_96[15:0]  = {ts_96_fns_reg, 16'd0} >> FNS_WIDTH;
204	    assign output_ts_64[63:16] = ts_64_ns_reg;
205	    assign output_ts_64[15:0]  = {ts_64_fns_reg, 16'd0} >> FNS_WIDTH;
206	    assign output_ts_step = ts_step_reg;
207	
208	    assign output_pps = pps_reg;
209	
210	end
211	
212	endgenerate
213	
214	always @(posedge clk) begin
215	    ts_step_reg <= 0;
216	
217	    // latch parameters
218	    if (input_period_valid) begin
219	        period_ns_reg <= input_period_ns;
220	        period_fns_reg <= input_period_fns;
221	    end
222	
223	    if (input_adj_valid) begin
224	        adj_ns_reg <= input_adj_ns;
225	        adj_fns_reg <= input_adj_fns;
226	        adj_count_reg <= input_adj_count;
227	    end
228	
229	    if (DRIFT_ENABLE && input_drift_valid) begin
230	        drift_ns_reg <= input_drift_ns;
231	        drift_fns_reg <= input_drift_fns;
232	        drift_rate_reg <= input_drift_rate;
233	    end
234	
235	    // timestamp increment calculation
236	    {ts_inc_ns_reg, ts_inc_fns_reg} <= $signed({1'b0, period_ns_reg, period_fns_reg}) +
237	        (adj_active_reg ? $signed({adj_ns_reg, adj_fns_reg}) : 0) +
238	        ((DRIFT_ENABLE && drift_cnt == 0) ? $signed({drift_ns_reg, drift_fns_reg}) : 0);
239	
240	    // offset adjust counter
241	    if (adj_count_reg > 0) begin
242	        adj_count_reg <= adj_count_reg - 1;
243	        adj_active_reg <= 1;
244	        ts_step_reg <= 1;
245	    end else begin
246	        adj_active_reg <= 0;
247	    end
248	
249	    // drift counter
250	    if (drift_cnt == 0) begin
251	        drift_cnt <= drift_rate_reg-1;
252	    end else begin
253	        drift_cnt <= drift_cnt - 1;
254	    end
255	
256	    // 96 bit timestamp
257	    {ts_inc_ns_delay_reg, ts_inc_fns_delay_reg} <= {ts_inc_ns_reg, ts_inc_fns_reg};
258	    {ts_inc_ns_ovf_reg, ts_inc_fns_ovf_reg} <= {NS_PER_S, {FNS_WIDTH{1'b0}}} - {ts_inc_ns_reg, ts_inc_fns_reg};
259	
260	    {ts_96_ns_inc_reg, ts_96_fns_inc_reg} <= {ts_96_ns_inc_reg, ts_96_fns_inc_reg} + {ts_inc_ns_delay_reg, ts_inc_fns_delay_reg};
261	    {ts_96_ns_ovf_reg, ts_96_fns_ovf_reg} <= {ts_96_ns_inc_reg, ts_96_fns_inc_reg} - {ts_inc_ns_ovf_reg, ts_inc_fns_ovf_reg};
262	    {ts_96_ns_reg, ts_96_fns_reg} <= {ts_96_ns_inc_reg, ts_96_fns_inc_reg};
263	
264	    if (!ts_96_ns_ovf_reg[30]) begin
265	        // if the overflow lookahead did not borrow, one second has elapsed
266	        // increment seconds field, pre-compute normal increment, force overflow lookahead borrow bit set
267	        {ts_96_ns_inc_reg, ts_96_fns_inc_reg} <= {ts_96_ns_ovf_reg, ts_96_fns_ovf_reg} + {ts_inc_ns_delay_reg, ts_inc_fns_delay_reg};
268	        ts_96_ns_ovf_reg[30] <= 1'b1;
269	        {ts_96_ns_reg, ts_96_fns_reg} <= {ts_96_ns_ovf_reg, ts_96_fns_ovf_reg};
270	        ts_96_s_reg <= ts_96_s_reg + 1;
271	    end
272	
273	    if (input_ts_96_valid) begin
274	        // load timestamp
275	        ts_96_s_reg <= input_ts_96[95:48];
276	        ts_96_ns_reg <= input_ts_96[45:16];
277	        ts_96_ns_inc_reg <= input_ts_96[45:16];
278	        ts_96_ns_ovf_reg[30] <= 1'b1;
279	        ts_96_fns_reg <= FNS_WIDTH > 16 ? input_ts_96[15:0] << (FNS_WIDTH-16) : input_ts_96[15:0] >> (16-FNS_WIDTH);
280	        ts_96_fns_inc_reg <= FNS_WIDTH > 16 ? input_ts_96[15:0] << (FNS_WIDTH-16) : input_ts_96[15:0] >> (16-FNS_WIDTH);
281	        ts_step_reg <= 1;
282	    end
283	
284	    // 64 bit timestamp
285	    {ts_64_ns_reg, ts_64_fns_reg} <= {ts_64_ns_reg, ts_64_fns_reg} + {ts_inc_ns_reg, ts_inc_fns_reg};
286	
287	    if (input_ts_64_valid) begin
288	        // load timestamp
289	        {ts_64_ns_reg, ts_64_fns_reg} <= input_ts_64;
290	        ts_step_reg <= 1;
291	    end
292	
293	    pps_reg <= !ts_96_ns_ovf_reg[30];
294	
295	    if (rst) begin
296	        period_ns_reg <= PERIOD_NS;
297	        period_fns_reg <= PERIOD_FNS;
298	        adj_ns_reg <= 0;
299	        adj_fns_reg <= 0;
300	        adj_count_reg <= 0;
301	        adj_active_reg <= 0;
302	        drift_ns_reg <= DRIFT_NS;
303	        drift_fns_reg <= DRIFT_FNS;
304	        drift_rate_reg <= DRIFT_RATE;
305	        ts_96_s_reg <= 0;
306	        ts_96_ns_reg <= 0;
307	        ts_96_fns_reg <= 0;
308	        ts_96_ns_inc_reg <= 0;
309	        ts_96_fns_inc_reg <= 0;
310	        ts_96_ns_ovf_reg[30] <= 1'b1;
311	        ts_64_ns_reg <= 0;
312	        ts_64_fns_reg <= 0;
313	        ts_step_reg <= 0;
314	        drift_cnt <= 0;
315	        pps_reg <= 0;
316	    end
317	end
318	
319	endmodule
320	
321	`resetall
322

